import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(bool shouldPause) public {
        // Set up: if shouldPause is true, pause the contract via the keeper role.
        // Note: The fuzzer will explore both shouldPause = false and true.
        address keeper = address(0x1);
        c.setKeeper(keeper);
        if (shouldPause) {
            vm.prank(keeper);
            c.pauseDeposit();
        }

        // The universal property: paused() must return the same boolean as the actual pause state.
        // The bug makes paused() always return true, violating this when shouldPause is false.
        bool expectedPaused = shouldPause;
        bool actualPaused = c.paused();
        assertTrue(actualPaused == expectedPaused);
    }
}

