pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        // Minimal initialization needed to avoid Ownable revert on some calls.
        // We need to call initialize to set the owner and internal state.
        // We'll deploy fakes for the required constructor arguments.
        // Since the test only calls paused(), we don't need to fully wire the fakes;
        // but initialize enforces initializer so we call it once.
        // Address(1) etc. are dummy addresses.
        c.initialize(
            IERC20(address(1)),
            IERC20(address(2)),
            IRewardRouterV2(address(3)),
            IGlpManager(address(4)),
            address(5),
            address(6)
        );
    }
    function testFuzz_property(uint256 _unused) public {
        // The state of 'paused' can be true or false depending on previous
        // external calls. We just read the value of paused() and compare it
        // with the value obtained by triggering the pause/unpause logic.
        // Since there is no public getter for the internal _paused flag,
        // we use the fact that calling _pause() twice reverts.
        // Strategy:
        // First, make sure the owner (this test contract) calls pauseDeposit
        // to force the contract into the paused state.
        // Then unpauseDeposit to force the contract into the unpaused state.
        // Between these steps we call paused() and assert its value.

        // We start as owner, because setUp called initialize which sets deployer as owner.
        // We need to make sure we can call the keeper-restricted functions.
        // Set the keeper to ourselves as well.
        c.setKeeper(address(this));

        // Ensure we start in a consistent state: unpause if currently paused.
        // We can't check paused() directly before toggling, because that's what we're testing.
        // Instead, we call unpauseDeposit in a try/catch to handle the case where it's already unpaused.
        try c.unpauseDeposit() { } catch { }

        // Now we are in the unpaused state. paused() should return false.
        bool pausedAfterUnpause = c.paused();

        // Now pause the contract.
        c.pauseDeposit();

        // paused() should return true.
        bool pausedAfterPause = c.paused();

        // We now have two values: paused when unpaused, and paused when paused.
        // In the reference implementation:
        // pausedAfterUnpause == false, and pausedAfterPause == true.
        // In the buggy implementation (always true): both will be true.
        // So the rule is: pausedAfterUnpause != pausedAfterPause.
        // We assert that they are different.
        // If the bug is present, they are both true, and the assertion fails.
        assertTrue(pausedAfterUnpause != pausedAfterPause);
    }
}
