pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address keeper, uint256 amount, address receiver) public {
        vm.assume(keeper != address(0));
        vm.assume(receiver != address(0));
        vm.assume(amount > 0 && amount < type(uint128).max / 2);

        // Setup: initialize contract with the fuzzed keeper
        // Use mock addresses for required interfaces that are not used in executeBatchStake path
        // We need to deploy actual mocks because glpManager.vault() is called.
        MockVault vault = new MockVault();
        MockGlpManager glpManager = new MockGlpManager(address(vault));
        MockERC20 usdc = new MockERC20();
        MockERC20 sGlp = new MockERC20();
        MockRewardRouter rewardRouter = new MockRewardRouter(address(glpManager));

        c.initialize(
            IERC20(address(sGlp)),
            IERC20(address(usdc)),
            IRewardRouterV2(address(rewardRouter)),
            IGlpManager(address(glpManager)),
            address(this),
            keeper
        );

        // Grant allowance so depositUsdc works
        usdc.setAllowance(address(c), type(uint256).max);

        // Fund sender and deposit USDC to set up roundUsdcBalance
        vm.prank(keeper);
        // We need prank as keeper for executeBatchStake later, but first deposit
        // depositUsdc can be called by anyone
        usdc.mint(address(this), amount);
        c.depositUsdc(amount, receiver);

        // Prank keeper for executeBatchStake
        vm.prank(keeper);
        c.executeBatchStake();

        // After executeBatchStake, contract should be paused
        assertTrue(c.paused());
    }
}

// Minimal mocks to satisfy the interface requirements
contract MockERC20 is IERC20 {
    mapping(address => uint256) public override balanceOf;
    mapping(address => mapping(address => uint256)) public override allowance;
    uint256 public override totalSupply;

    function mint(address to, uint256 amount) external {
        balanceOf[to] += amount;
        totalSupply += amount;
        emit Transfer(address(0), to, amount);
    }

    function setAllowance(address spender, uint256 amount) external {
        allowance[msg.sender][spender] = amount;
    }

    function transfer(address to, uint256 amount) external override returns (bool) {
        require(balanceOf[msg.sender] >= amount, "insufficient balance");
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        emit Transfer(msg.sender, to, amount);
        return true;
    }

    function approve(address spender, uint256 amount) external override returns (bool) {
        allowance[msg.sender][spender] = amount;
        emit Approval(msg.sender, spender, amount);
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external override returns (bool) {
        require(allowance[from][msg.sender] >= amount, "insufficient allowance");
        require(balanceOf[from] >= amount, "insufficient balance");
        allowance[from][msg.sender] -= amount;
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        emit Transfer(from, to, amount);
        return true;
    }
}

contract MockGlpManager is IGlpManager {
    address public override vault;
    constructor(address _vault) { vault = _vault; }
}

contract MockVault is IVault {
    function getMinPrice(address) external pure override returns (uint256) {
        return 1e18; // 1 USD
    }
}

contract MockRewardRouter is IRewardRouterV2 {
    IGlpManager public glpManager;
    constructor(address _glpManager) { glpManager = IGlpManager(_glpManager); }

    function mintAndStakeGlp(address token, uint256 amount, uint256 minUsdg, uint256 minGlp) external override returns (uint256) {
        // Mock: just return the amount as glp staked
        return amount;
    }
}

