pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property() public {
        // Adversarial counterparty: a contract that can be set as the keeper to call pause/unpause
        // We deploy a helper that will act as keeper
        KeeperHelper helper = new KeeperHelper();

        // Initialize the contract with the helper as keeper
        // We need to provide some addresses for the IERC20 etc. - use the helper's address as a mock
        // Since we only test paused() behavior, the actual addresses don't matter for functional correctness
        // of pause/unpause, but initialize requires non-zero addresses to set up properly.
        // We'll use the helper address for all required dependencies to satisfy the initialization.
        c.initialize(
            IERC20(address(helper)),
            IERC20(address(helper)),
            IRewardRouterV2(address(helper)),
            IGlpManager(address(helper)),
            address(helper), // dnGmxJuniorVault
            address(helper)  // keeper
        );

        // Set the helper as the actual keeper (it already is, but for clarity)
        // The helper has a function to call pause/unpause on behalf of the contract
        helper.setContract(address(c));

        // Record the internal _paused state by observing the effect:
        // If we pause, then paused() should return true; if we unpause, it should return false.
        // We'll toggle the state and check consistency.

        // First, unpause to ensure we start from a known state
        // The contract is initialized unpaused by default, but let's be sure
        bool initiallyPaused = c.paused();

        // Toggle: if paused, unpause; if unpaused, pause
        if (initiallyPaused) {
            vm.prank(address(helper));
            c.unpauseDeposit();
        } else {
            vm.prank(address(helper));
            c.pauseDeposit();
        }

        bool afterToggle = c.paused();
        // After toggling, the paused state should be the opposite of what it was
        assertTrue(afterToggle != initiallyPaused);
    }
}

// Helper contract that acts as the keeper to call pause/unpause
contract KeeperHelper {
    C public target;

    function setContract(address _c) external {
        target = C(_c);
    }

    function pause() external {
        target.pauseDeposit();
    }

    function unpause() external {
        target.unpauseDeposit();
    }
}

